// Every duration a comment of the root module's code or a decision record
// quotes is in docs/benchmarks.md, within the figures' tolerance — as
// TestGuideFiguresHaveASource holds the guides' and TestRatiosHaveASource
// every multiple. The godoc and the records escaped both: window.go said
// 4.5 ns per element where the page, regenerated, said 5.43.
func TestDurationsHaveASource(t *testing.T) {
	page, err := os.ReadFile("docs/benchmarks.md")
	if err != nil {
		t.Fatal(err)
	}
	measured := measuredIn(string(page))
	files, err := filepath.Glob("docs/design/adr/*.md")
	if err != nil {
		t.Fatal(err)
	}
	err = filepath.WalkDir(".", func(p string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if p == "." {
				return nil
			}
			if strings.HasPrefix(d.Name(), ".") || d.Name() == "testdata" {
				return filepath.SkipDir
			}
			if _, err := os.Stat(filepath.Join(p, "go.mod")); err == nil {
				return filepath.SkipDir // a nested module, outside the promise of the docs
			}
			return nil
		}
		if strings.HasSuffix(p, ".go") && !strings.HasSuffix(p, "_test.go") {
			files = append(files, p)
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range files {
		b, err := os.ReadFile(f) //nolint:gosec // G304: a repository path, not input
		if err != nil {
			t.Fatal(err)
		}
		for _, e := range unsourcedDurationsIn(f, string(b), string(page), measured) {
			t.Error(e)
		}
	}
}

// A paragraph that names its section of docs/benchmarks.md is held to that
// section: the page holds hundreds of durations, and more than half of those
// of a decade lie within the tolerance of another, so a stale figure checked
// against the whole page passed — window.go's 4.5 ns, where its section says
// 5.43.
func TestDurationsAreReadInTheSectionTheyCite(t *testing.T) {
	page, err := os.ReadFile("docs/benchmarks.md")
	if err != nil {
		t.Fatal(err)
	}
	src, err := os.ReadFile("window/window.go")
	if err != nil {
		t.Fatal(err)
	}
	const quoted = "Measured at 5.43 ns/element"
	if !strings.Contains(string(src), quoted) {
		t.Fatalf("window/window.go no longer says %q: the witness needs another figure", quoted)
	}
	stale := strings.Replace(string(src), quoted, "Measured at 4.5 ns/element", 1)
	errs := unsourcedDurationsIn("window/window.go", stale, string(page), measuredIn(string(page)))
	if !slices.ContainsFunc(errs, func(e string) bool { return strings.Contains(e, "4.5 ns") }) {
		t.Errorf("window.go quoting 4.5 ns against a section that says 5.43 passed: %v", errs)
	}
}

// A paragraph that names a benchmark without citing a section is held to
// the paragraphs and rows of docs/benchmarks.md that name it: Async's
// +0.31 ns per element passed against the whole page, inside the tolerance
// of some other figure, where no line of the page measured it.
func TestDurationsAreReadInTheRowsTheyName(t *testing.T) {
	page, err := os.ReadFile("docs/benchmarks.md")
	if err != nil {
		t.Fatal(err)
	}
	src, err := os.ReadFile("parallel/parallelunordered.go")
	if err != nil {
		t.Fatal(err)
	}
	const quoted, wrong = "against 3.47 ms here", "against 445 µs here"
	if !strings.Contains(string(src), quoted) {
		t.Fatalf("parallel/parallelunordered.go no longer says %q: the witness needs another figure", quoted)
	}
	whole := measuredIn(string(page))
	if !slices.ContainsFunc(whole, func(w float64) bool { return relative(445e3, w) <= figureTolerance }) {
		t.Fatal("445 µs is no longer a figure of docs/benchmarks.md: the witness no longer shows the narrowing")
	}
	stale := strings.Replace(string(src), quoted, wrong, 1)
	errs := unsourcedDurationsIn("parallel/parallelunordered.go", stale, string(page), whole)
	if !slices.ContainsFunc(errs, func(e string) bool { return strings.Contains(e, "445 µs") }) {
		t.Errorf("parallelunordered.go quoting 445 µs under BenchmarkParallelUnorderedSkewed, whose row says 3,465 µs, passed: %v", errs)
	}
}

// citedSection is the section of docs/benchmarks.md a paragraph names, as
// `docs/benchmarks.md, "Title"`, wrapped across lines or not; benchName is a
// benchmark a paragraph names, which narrows it to that benchmark's rows.
var (
	citedSection = regexp.MustCompile(`docs/benchmarks\.md, "([^"]+)"`)
	benchName    = regexp.MustCompile(`\bBenchmark[A-Z][A-Za-z0-9_]*`)
)

// sectionTitled finds the section a citation names: by its title, or by the
// start of it — a heading may carry a date the citation leaves out.
func sectionTitled(bySection map[string]string, title string) (string, bool) {
	slug := slugOf(title)
	if s, ok := bySection[slug]; ok {
		return s, true
	}
	best := ""
	for k := range bySection {
		if strings.HasPrefix(k, slug+"-") && (best == "" || len(k) < len(best)) {
			best = k
		}
	}
	return bySection[best], best != ""
}

// linesNaming is the part of page that states figures for the benchmarks
// named: every paragraph that names one, with the table that follows it, and
// every table row that names one, with the header of its table, so that
// measuredIn still reads the row's bare figures in the unit the header gives
// them. A paragraph names its benchmark once and states its figures on the
// lines after; a row states them beside the name.
func linesNaming(page string, names []string) string {
	quoted := make([]string, len(names))
	for i, n := range names {
		quoted[i] = regexp.QuoteMeta(n)
	}
	named := regexp.MustCompile(`\b(?:` + strings.Join(quoted, "|") + `)\b`)
	// The page as blocks: a paragraph, a table, a heading, a fence — each
	// ended by a blank line or by a change between table and prose.
	var blocks [][]string
	var cur []string
	table := false
	for _, line := range strings.Split(page, "\n") {
		isRow := strings.HasPrefix(line, "|")
		if strings.TrimSpace(line) == "" || (len(cur) > 0 && isRow != table) {
			if len(cur) > 0 {
				blocks = append(blocks, cur)
			}
			cur = nil
		}
		if strings.TrimSpace(line) != "" {
			cur = append(cur, line)
			table = isRow
		}
	}
	if len(cur) > 0 {
		blocks = append(blocks, cur)
	}
	var out []string
	followed := false // the block before named a benchmark in its prose
	for _, b := range blocks {
		isTable := strings.HasPrefix(b[0], "|")
		switch {
		case isTable && followed:
			out = append(out, "")
			out = append(out, b...)
		case isTable:
			var rows []string
			for _, row := range b[min(2, len(b)):] {
				if named.MatchString(row) {
					rows = append(rows, row)
				}
			}
			if len(rows) > 0 {
				out = append(out, "")
				out = append(out, b[:min(2, len(b))]...)
				out = append(out, rows...)
			}
		case named.MatchString(strings.Join(b, " ")):
			out = append(out, "")
			out = append(out, b...)
		}
		followed = !isTable && named.MatchString(strings.Join(b, " "))
	}
	return strings.Join(out, "\n")
}

// unsourcedDurationsIn checks the durations of one file — its comments for
// Go, all of it for a decision record — paragraph by paragraph: a paragraph
// that cites a section of page against that section's figures, any other
// against whole, every figure of the page.
func unsourcedDurationsIn(f, text, page string, whole []float64) []string {
	bySection := sections(page)
	goFile := strings.HasSuffix(f, ".go")
	lines := strings.Split(text, "\n")
	var errs []string
	var para []int // line indexes of the paragraph being read
	flush := func() {
		if len(para) == 0 {
			return
		}
		var joined []string
		for _, i := range para {
			joined = append(joined, strings.TrimPrefix(strings.TrimSpace(lines[i]), "//"))
		}
		flat := strings.Join(strings.Fields(strings.Join(joined, " ")), " ")
		pool, where := whole, "in no table or sentence of docs/benchmarks.md"
		if m := citedSection.FindStringSubmatch(flat); m != nil {
			section, ok := sectionTitled(bySection, m[1])
			if !ok {
				errs = append(errs, fmt.Sprintf("%s:%d: cites %q, a section docs/benchmarks.md does not have", f, para[0]+1, m[1]))
			}
			pool, where = measuredIn(section), fmt.Sprintf("not in %q, the section of docs/benchmarks.md its paragraph cites", m[1])
			// Naming the benchmarks as well narrows it to their rows: a
			// section holds figures of many, and a stale one sits within the
			// tolerance of some other as often as not.
			if names := benchName.FindAllString(flat, -1); len(names) > 0 {
				pool = measuredIn(linesNaming(section, names))
				where = fmt.Sprintf("in no row of %q naming %s, which its paragraph names", m[1], strings.Join(names, " or "))
			}
		} else if names := benchName.FindAllString(flat, -1); len(names) > 0 {
			// A benchmark named without its section narrows the page the
			// same way: the figure is that benchmark's, wherever it sits.
			pool = measuredIn(linesNaming(page, names))
			where = fmt.Sprintf("in no paragraph or row of docs/benchmarks.md naming %s, which its paragraph names", strings.Join(names, " or "))
		}
		for _, i := range para {
			for _, m := range duration.FindAllStringSubmatch(lines[i], -1) {
				if _, ok := unsourcedDurations[f+" "+m[0]]; ok {
					continue
				}
				v := nanos(m)
				if !slices.ContainsFunc(pool, func(w float64) bool { return relative(v, w) <= figureTolerance }) {
					errs = append(errs, fmt.Sprintf("%s:%d: %s is %s", f, i+1, m[0], where))
				}
			}
		}
		para = para[:0]
	}
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		switch {
		case goFile && (!strings.HasPrefix(trimmed, "//") || trimmed == "//"):
			flush()
		case !goFile && trimmed == "":
			flush()
		default:
			para = append(para, i)
		}
	}
	flush()
	return errs
}
